const androidTasksGeneratedMarker =
    '// Generated by miniprogram embed init --android-separate-tasks. Do not edit.';

String buildAndroidTaskChannel(String packageName, {bool aiAssistant = false}) {
  final source =
      'package $packageName\n\n$androidTasksGeneratedMarker\n'
      r'''
import android.app.Activity
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.embedding.engine.plugins.FlutterPlugin
import io.flutter.embedding.engine.plugins.activity.ActivityAware
import io.flutter.embedding.engine.plugins.activity.ActivityPluginBinding
import io.flutter.plugin.common.MethodCall
import io.flutter.plugin.common.MethodChannel

internal class MiniProgramTaskChannel : FlutterPlugin, ActivityAware {
    companion object {
        fun register(flutterEngine: FlutterEngine) {
            MiniProgramInteractionRelay.register(flutterEngine)
            if (!flutterEngine.plugins.has(MiniProgramTaskChannel::class.java)) {
                flutterEngine.plugins.add(MiniProgramTaskChannel())
            }
        }
    }

    private var channel: MethodChannel? = null
    private var activity: Activity? = null

    override fun onAttachedToEngine(binding: FlutterPlugin.FlutterPluginBinding) {
        channel = MethodChannel(binding.binaryMessenger, "mini_program/android_tasks").also {
            it.setMethodCallHandler(::handleCall)
        }
    }

    override fun onDetachedFromEngine(binding: FlutterPlugin.FlutterPluginBinding) {
        channel?.setMethodCallHandler(null)
        channel = null
        activity = null
    }

    override fun onAttachedToActivity(binding: ActivityPluginBinding) { activity = binding.activity }
    override fun onReattachedToActivityForConfigChanges(binding: ActivityPluginBinding) {
        activity = binding.activity
    }
    override fun onDetachedFromActivityForConfigChanges() { activity = null }
    override fun onDetachedFromActivity() { activity = null }

    private fun handleCall(call: MethodCall, result: MethodChannel.Result) {
        if (call.method != "openMiniProgram" && call.method != "showHost") {
            result.notImplemented()
            return
        }
        val current = activity
        if (current == null) {
            result.error("mini_program_task_unavailable", "No attached Android Activity.", null)
            return
        }
        try {
            when (call.method) {
                "openMiniProgram" -> {
                    val appId = call.argument<String>("appId")?.trim().orEmpty()
                    val title = call.argument<String>("title") ?: appId
                    if (appId.isEmpty() || appId.length > 256 || title.length > 256) {
                        result.error("invalid_mini_program", "A bounded appId and title are required.", null)
                        return
                    }
                    MiniProgramTaskActivity.openMiniProgram(
                        current, appId, title,
                        call.argument<Boolean>("showAppBar") ?: true,
                        call.argument<Number>("backgroundColor")?.toLong() ?: 0xFFF8FAFCL,
                    )
                }
                "showHost" -> MiniProgramTaskActivity.showHost(current)
            }
            result.success(null)
        } catch (error: MiniProgramTaskLimitException) {
            result.error("mini_program_task_limit", error.message, null)
        } catch (error: Exception) {
            result.error("mini_program_task_unavailable", error.message, null)
        }
    }
}
''';
  return aiAssistant
      ? source.replaceFirst(
          '            MiniProgramInteractionRelay.register(flutterEngine)',
          '            MiniProgramInteractionRelay.register(flutterEngine)\n'
              '            HostAiSessionRelay.register(flutterEngine)',
        )
      : source;
}

String buildAndroidTaskActivity(String packageName) =>
    'package $packageName\n\n$androidTasksGeneratedMarker\n'
    r'''
import android.app.Activity
import android.app.ActivityManager
import android.content.Context
import android.content.Intent
import android.net.Uri
import android.os.Build
import android.os.Bundle
import android.window.OnBackInvokedCallback
import android.window.OnBackInvokedDispatcher
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import androidx.core.view.WindowInsetsControllerCompat
import io.flutter.embedding.android.FlutterFragmentActivity
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.MethodChannel

/** Each slot has its own Activity, task affinity, Flutter engine, and live state. */
abstract class MiniProgramTaskActivity : FlutterFragmentActivity() {
    private var backCallback: OnBackInvokedCallback? = null
    private var backRequestPending = false

    companion object {
        private const val APP_ID = "mini_program_app_id"
        private const val TITLE = "mini_program_title"
        private const val SHOW_APP_BAR = "mini_program_show_app_bar"
        private const val BACKGROUND_COLOR = "mini_program_background_color"
        private val activities = listOf(
            MiniProgramTaskActivity0::class.java,
            MiniProgramTaskActivity1::class.java,
            MiniProgramTaskActivity2::class.java,
            MiniProgramTaskActivity3::class.java,
            MiniProgramTaskActivity4::class.java,
        )

        private fun appIdForIntent(source: Intent?, packageName: String): String {
            source?.getStringExtra(APP_ID)?.takeIf { it.isNotBlank() }?.let { return it }
            // Restored task records can retain data while losing launch extras.
            val uri = source?.data ?: return ""
            if (uri.scheme != "miniprogram" || uri.authority != packageName ||
                uri.pathSegments.size != 2 || uri.pathSegments.first() != "active") return ""
            return uri.lastPathSegment.orEmpty()
        }

        fun openMiniProgram(
            context: Context, appId: String, title: String,
            showAppBar: Boolean, backgroundColor: Long,
        ) {
            val manager = context.getSystemService(Context.ACTIVITY_SERVICE) as ActivityManager
            val tasks = manager.appTasks
            val slot = selectMiniProgramTaskSlot(
                appId, activities.map { it.name },
                tasks.map { task ->
                    val info = task.taskInfo
                    MiniProgramTaskRecord(
                        info.taskId, info.baseIntent?.component?.className.orEmpty(),
                        appIdForIntent(info.baseIntent, context.packageName),
                    )
                },
            )
            val existing = tasks.firstOrNull { it.taskInfo.taskId == slot.existingTaskId }
            if (existing != null) {
                existing.moveToFront()
                return
            }
            context.startActivity(Intent(context, activities.first { it.name == slot.activityClassName }).apply {
                action = Intent.ACTION_VIEW
                data = Uri.Builder().scheme("miniprogram").authority(context.packageName)
                    .appendPath("active").appendPath(appId).build()
                addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                putExtra(APP_ID, appId)
                putExtra(TITLE, title)
                putExtra(SHOW_APP_BAR, showAppBar)
                putExtra(BACKGROUND_COLOR, backgroundColor)
            })
        }

        fun showHost(activity: Activity) {
            val manager = activity.getSystemService(Context.ACTIVITY_SERVICE) as ActivityManager
            val host = manager.appTasks.firstOrNull { task ->
                task.taskInfo.baseIntent?.component?.className == MainActivity::class.java.name ||
                    task.taskInfo.topActivity?.className == MainActivity::class.java.name
            }
            if (host != null) {
                host.moveToFront()
            } else {
                activity.startActivity(Intent(activity, MainActivity::class.java).apply {
                    addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_SINGLE_TOP)
                })
            }
        }
    }

    override fun getDartEntrypointFunctionName(): String = "miniProgramTaskMain"

    override fun getInitialRoute(): String = Uri.Builder()
        .appendPath("mini-program").appendPath(appIdForIntent(intent, packageName))
        .appendQueryParameter("title", intent.getStringExtra(TITLE) ?: appIdForIntent(intent, packageName))
        .appendQueryParameter("showAppBar", intent.getBooleanExtra(SHOW_APP_BAR, true).toString())
        .appendQueryParameter("backgroundColor", intent.getLongExtra(BACKGROUND_COLOR, 0xFFF8FAFCL).toString())
        .build().toString()

    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
        super.configureFlutterEngine(flutterEngine)
        MiniProgramNativeSetup.register(flutterEngine)
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        @Suppress("DEPRECATION")
        setTaskDescription(ActivityManager.TaskDescription(intent.getStringExtra(TITLE) ?: appIdForIntent(intent, packageName)))
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            val callback = OnBackInvokedCallback { handleBack() }
            backCallback = callback
            onBackInvokedDispatcher.registerOnBackInvokedCallback(
                OnBackInvokedDispatcher.PRIORITY_DEFAULT, callback,
            )
        }
    }

    override fun onDestroy() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            backCallback?.let { onBackInvokedDispatcher.unregisterOnBackInvokedCallback(it) }
        }
        backCallback = null
        super.onDestroy()
    }

    @Suppress("DEPRECATION")
    override fun onBackPressed() { handleBack() }

    private fun handleBack() {
        if (backRequestPending || isFinishing || isDestroyed) return
        val view = window.decorView
        if (ViewCompat.getRootWindowInsets(view)?.isVisible(WindowInsetsCompat.Type.ime()) == true) {
            WindowInsetsControllerCompat(window, view).hide(WindowInsetsCompat.Type.ime())
            return
        }
        val messenger = flutterEngine?.dartExecutor?.binaryMessenger
        if (messenger == null) {
            showHost(this)
            return
        }
        backRequestPending = true
        MethodChannel(messenger, "mini_program/android_tasks").invokeMethod(
            "handleBack", null, object : MethodChannel.Result {
                private fun complete(handled: Boolean) {
                    backRequestPending = false
                    if (!handled && !isFinishing && !isDestroyed && hasWindowFocus()) {
                        showHost(this@MiniProgramTaskActivity)
                    }
                }
                override fun success(result: Any?) { complete(result == true) }
                override fun error(code: String, message: String?, details: Any?) { complete(false) }
                override fun notImplemented() { complete(false) }
            },
        )
    }
}

class MiniProgramTaskActivity0 : MiniProgramTaskActivity()
class MiniProgramTaskActivity1 : MiniProgramTaskActivity()
class MiniProgramTaskActivity2 : MiniProgramTaskActivity()
class MiniProgramTaskActivity3 : MiniProgramTaskActivity()
class MiniProgramTaskActivity4 : MiniProgramTaskActivity()
''';

String buildAndroidTaskSlots(String packageName) =>
    'package $packageName\n\n$androidTasksGeneratedMarker\n'
    r'''
internal data class MiniProgramTaskRecord(
    val taskId: Int, val activityClassName: String, val appId: String,
)
internal data class MiniProgramTaskSlot(
    val activityClassName: String, val existingTaskId: Int? = null,
)
internal class MiniProgramTaskLimitException : IllegalStateException(
    "All five mini-program tasks are in use. Close one from Recent apps before opening another.",
)

/** Android task records remain the ownership source after process recreation. */
internal fun selectMiniProgramTaskSlot(
    appId: String, activityClassNames: List<String>, tasks: List<MiniProgramTaskRecord>,
): MiniProgramTaskSlot {
    val owned = tasks.filter { it.activityClassName in activityClassNames }
    owned.firstOrNull { it.appId == appId }?.let {
        return MiniProgramTaskSlot(it.activityClassName, it.taskId)
    }
    val occupied = owned.map { it.activityClassName }.toSet()
    val available = activityClassNames.firstOrNull { it !in occupied }
        ?: throw MiniProgramTaskLimitException()
    return MiniProgramTaskSlot(available)
}
''';
